const tabId = 583778164;
const allPhotos = await browserjs(tabId, async () => {
  const res = await fetch("/api.php?action=query&list=categorymembers&cmtitle=Category:Images_of_Trinity&cmlimit=200&cmtype=file&format=json");
  const data = await res.json();
  const members = data.query?.categorymembers || [];

  // Get image info for each
  const titles = members.map(m => m.title).join("|");
  const imgRes = await fetch("/api.php?action=query&titles=" + encodeURIComponent(titles) + "&prop=imageinfo&iiprop=url|size|mime&format=json");
  const imgData = await imgRes.json();

  const pages = imgData.query?.pages || {};
  const results = Object.values(pages).map(p => ({
    title: p.title,
    url: p.imageinfo?.[0]?.url,
    descUrl: p.imageinfo?.[0]?.descriptionurl,
    size: p.imageinfo?.[0]?.size,
    mime: p.imageinfo?.[0]?.mime
  }));

  return results;
});

